use crate::domains::kernel_opt::corpus::KernelRule;

/// Data table, not logic -- grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // ── A: the STORE-side L2 policy axis -- pin produced lines that a
        // later consumer reads across an intervening weight stream ──────
        // Source: memory.cuh:94-101 (store_u64_evict_last) + the pin
        // commit itself ("warm the next GDN layer's state in L2 during
        // replay records") -- the concrete instantiation.
        KernelRule {
            rule_id: "producer-store-evict-last-pins-cross-stream-consumer".to_string(),
            gpu_concept: "The STORE side of the L2 residency policy: when a kernel STORES a small record that a LATER kernel consumes, and the two are separated by a weight stream far larger than L2, tag the store with an evict-last fill policy so the line survives the intervening stream. Source contract, verbatim (memory.cuh:94-95): 'Stores a key whose consumer runs after a larger weight stream: the evict-last fill keeps the line in L2 until that consumer reads it.' Mechanism (sm_80+, works on the 4090): `createpolicy.fractional.L2::evict_last` composed into `st.global.L2::cache_hint` -- a pure cache-policy hint, ZERO arithmetic change, bit-identical by construction (the same class as the load-side evict-first rule's correctness-neutral clause). This is the third member of the L2-policy trio the source ships (evict-first LOAD fills for streamed weights / evict-last STORE fills for produced records / `discard.global.L2` for dead lines) -- the trio is one decision family: WHO owns the L2 line's lifetime, decided per access by the data's consumer graph, not left to the default policy. The concrete instantiation IS the batch pin commit ('perf: warm the next GDN layer's state in L2 during replay records'): the GDN replay records a layer writes are consumed by the NEXT layer, with the whole layer weight stream in between -- without the hint the records are evicted and refetched every layer (the source's own working-set argument: evict-first weight fills 'leave the small activation and record working set resident across layers instead of writing it back and refetching it every layer'). REGIME: producer->consumer pair separated by a working-set-larger-than-L2 stream, produced set SMALL relative to L2. ANTI-REGIME: consumer adjacent (same kernel or immediately next -- default policy is fine, the hint costs a policy register for nothing), or the produced set itself approaching L2 size (evict-last pins THRASH -- pinning a set larger than its capacity evicts itself). Measured (source-reported, composite pass-1 attribution, RTX 5090): the verify-round series -16.6/-19.2/-22.6% @8K/32K/131K and tok/s +19.8/+28.3/+29.2% carries this rule among the pass-1 mechanisms (no per-kernel split -- the honest composite caveat); the fifth-pass sweep reads 19-28% shorter rounds vs `b4e8ed4` from 32K up. KINSHIP, compose: weight-stream-non-temporal-loads (entries_gpu_07) is the LOAD-side complement -- evict-FIRST on the stream that must NOT stay, evict-LAST on the record that MUST; dead-line-l2-discard-after-last-consumer (same batch) closes the lifetime at the END (the consumed line's eviction). Distinct from every staging/copy rule (no data moves -- the policy hint replaces a refetch), from l2-grouped-tile-schedule (schedules TILE ORDER for locality; this decides LINE LIFETIME independent of order). Source: satellitedown/cinference @ 37814b1e -- src/ops/common/memory.cuh:94-101 + the pin commit message + NOTICE (the replay-record warm). Batch 178 / Plan 171 / Research 209.".to_string(),
            ref_shape: "// naive: the per-layer record store rides the default L2 policy. The\n// next layer's consumer sits a whole weight-stream away (>> L2), so the\n// line is evicted before its consumer and refetched every layer.\nfn store_record_default(record: &mut [u64], slot: usize, value: u64) {\n    record[slot] = value; // default policy: line is LRU -- the weight stream evicts it\n}\n\nfn layer_loop_naive(records: &mut [u64], weights_stream: &[u8]) -> u64 {\n    let mut acc = 0u64;\n    for layer in 0..weights_stream.len() {\n        store_record_default(records, layer, acc.wrapping_mul(3));\n        // ... the layer's weight stream runs here (>> L2, evicts the record) ...\n        acc = acc.wrapping_add(records[layer] as u64); // REFETCH: the consumer missed\n    }\n    acc\n}".to_string(),
            opt_pattern: "// optimized: the store carries an evict-last fill policy -- the produced\n// line is pinned in L2 across the intervening weight stream until its\n// consumer reads it. A pure hint: same bytes, same order, bit-identical.\n#[derive(Clone, Copy)]\nenum L2FillPolicy {\n    Default,   // LRU -- the stream decides\n    EvictLast, // pin: the line stays until read\n    EvictFirst, // stream: the line leaves immediately\n}\n\nfn store_record_evict_last(record: &mut [u64], slot: usize, value: u64, policy: L2FillPolicy) {\n    // createpolicy.fractional.L2::evict_last -> st.global.L2::cache_hint\n    let _ = policy; // the hint rides the STORE instruction's cache-policy operand\n    record[slot] = value; // same write -- the LINE's lifetime is what changed\n}\n\nfn layer_loop_pinned(records: &mut [u64], weights_stream: &[u8]) -> u64 {\n    let mut acc = 0u64;\n    for layer in 0..weights_stream.len() {\n        // produced set SMALL vs L2, consumer = next layer, separator = the\n        // weight stream: the pin regime holds\n        store_record_evict_last(records, layer, acc.wrapping_mul(3), L2FillPolicy::EvictLast);\n        // ... the layer's weight stream runs here -- the record line SURVIVES ...\n        acc = acc.wrapping_add(records[layer] as u64); // L2 hit: no refetch\n    }\n    acc\n}".to_string(),
        },

        // ── A: capacity reclamation for dead lines -- the safety contract
        // IS the content ────────────────────────────────────────────────
        // Source: memory.cuh:103-107 (discard_l2_line) + NOTICE ("L2
        // discards of consumed attention split numerators") + pass commit
        // b7e1a8b.
        KernelRule {
            rule_id: "dead-line-l2-discard-after-last-consumer".to_string(),
            gpu_concept: "Reclaim L2 capacity for lines whose data is DEAD by discarding them in-place (`discard.global.L2`, sm_80+) instead of letting them write back or linger -- the decision content is the SAFETY CONTRACT, verbatim (memory.cuh:103-104): 'Invalidates the 128-byte L2 line at `line` without writing it back. Only for lines whose data is dead: every later read of the line must follow a new write.' Two hazards the contract names: (1) a discard BEFORE the last consumer serves garbage -- the line's bytes are undefined after the discard, so any remaining reader reads noise; (2) a discard of a DIRTY line silently drops the write -- the discard is not a writeback, it is an invalidation, so the data must already be consumed from L2 (or never needed again) at discard time. The instantiation (NOTICE, verbatim): 'L2 discards of consumed attention split numerators' -- the split-KV attention partials are written, consumed by the merge, and then dead; discarding them frees the line for the next layer's working set WITHOUT a DRAM writeback (a dead dirty line left to LRU costs a writeback it did not need). REGIME: a scratch/partial whose last consumer is known and in-kernel (split numerators, consumed temporaries, staging that will be overwritten); the discard goes AFTER the last read. ANTI-REGIME: any line a later pass MIGHT read (cross-kernel scratch with an unclear last reader -- the conservative default is no discard; a stale read is a correctness bug, a missed discard is only a perf loss); persistent data (the discard is not a free). Pure cache-control instruction: zero arithmetic, bit-identical by construction. Measured: rides the same source verify-round series (composite pass attribution; the pass commit 'perf: discard consumed K8V4 split numerators from L2' is in the series). KINSHIP, compose: producer-store-evict-last-pins-cross-stream-consumer (same batch) opens the line's lifetime and THIS rule closes it -- the pair is the full lifetime discipline (pin what a later consumer needs, discard what no consumer needs); weight-stream-non-temporal-loads is the third member (never let stream data claim the capacity at all). Distinct from smem reuse rules (those reuse REGISTER/SMEM allocations; this reclaims the L2 capacity a dead line still holds). Source: satellitedown/cinference @ 37814b1e -- src/ops/common/memory.cuh:103-107 + NOTICE. Batch 178 / Plan 171 / Research 209.".to_string(),
            ref_shape: "// naive: consumed split numerators are left in L2 to LRU out on their\n// own -- a dead DIRTY line eventually writes back to DRAM (bandwidth the\n// data never needed) and holds capacity until evicted.\nfn merge_and_abandon(numerators: &mut [f32], splits: usize, out: &mut [f32]) {\n    for s in 0..splits {\n        out[s] = numerators[s]; // consumed: the value is now dead in numerators[s]\n    }\n    // numerators left as-is: the dead lines linger, dirty lines write back\n}".to_string(),
            opt_pattern: "// optimized: after the LAST consumer reads a line, discard it -- the\n// line is invalidated without writeback, capacity returns immediately.\n// THE CONTRACT: every later read must follow a NEW write (discard AFTER\n// the last consumer, never before).\nfn merge_and_discard(numerators: &mut [f32], splits: usize, out: &mut [f32]) {\n    for s in 0..splits {\n        out[s] = numerators[s]; // the last (only) consumer\n    }\n    for chunk in numerators.chunks_mut(32) {\n        // discard.global.L2 [line], 128 -- one 128B line per 32 f32\n        let _ = chunk; // invalidates WITHOUT writeback; later reads need a new write\n    }\n    // capacity reclaimed for the next layer's working set; no dead writeback\n}".to_string(),
        },

        // ── D: sharing/update legality derived FROM THE CAPTURED GRAPH --
        // an order-sensitive signature over captured node types ──────────
        // Source: decode_graph.h:28-31 (the contract) + decode_graph.cpp:
        // 62-81 (the FNV-1a impl) + graphs.cpp:70-78 (the installed_profile
        // gate) + graphs.cpp:360-384 (the routing).
        KernelRule {
            rule_id: "graph-exec-update-gated-by-captured-topology-signature".to_string(),
            gpu_concept: "When many execution profiles (batch sizes x frontier buckets) must share CUDA-graph executables, derive the sharing class and the update legality FROM THE CAPTURED GRAPH ITSELF -- never from the construction parameters: an order-sensitive signature (node count + FNV-1a over each captured node's type, kernel nodes keyed by function identity) with equal signatures sharing ONE executable and profile switches going through `cudaGraphExecUpdate`, never re-instantiation. The header contract, verbatim (decode_graph.h:28-30): 'Node count and an order-sensitive hash of the captured node sequence. Profiles with different signatures capture different node topologies and must not share one executable: a CUDA graph executable can be updated across profiles only while the topology is unchanged.' WHY the captured graph and not the plan (graphs.cpp:360-362, verbatim): 'The frontier buckets cross engine-internal route boundaries that change the captured node topology. Those boundaries are not enumerable from the plan, so the class is derived from the capture itself: profiles with the same captured signature share one executable.' The gate (graphs.cpp:70-78): `if (topology.installed_profile != profile_index) { topology.executable.update(profile.definition); topology.installed_profile = profile_index; }` -- one executable per topology class, updated in place on class-internal switches. The legality of `cudaGraphExecUpdate` comes from the captured topology being unchanged -- SAME node sequence, kernel identities, and edges -- while node PARAMS (grid dims, pointers) may differ; a signature keyed on construction params cannot prove this (two plans can capture differently after an internal route boundary, and the boundary set is engine-internal). Cost class: instantiate is 10^2-10^3x an in-place update, so the signature pays for itself the first time it prevents a re-capture. Bit-identical by construction (runtime graph ops; zero arithmetic). REGIME: >= 2 profiles over the same workload family where MOST differ only in node params (the update path) and a bounded set differ in topology (the class split). ANTI-REGIME: every capture unique (no sharing to be had), or a single profile (nothing to gate). Benchable on OUR lane: the 4090 CUDA-graphs prefill lane (riir-infer-gpu, Issue 965 / RIIR_PREFILL_CUDA_GRAPHS) -- instantiate-vs-update at capture boundaries is directly measurable. Distinct from identity-keyed-graph-retention-stable-arena (retains graphs by CONSTRUCTION key + bucket arena; the key is built from what the caller knows -- this derives the key from what the CAPTURE proved, which is strictly stronger when internal routing is opaque), from captured-graph-bakes-buffer-addresses (drop-or-survive on address churn; this shares/updates within an address-stable family), from device-m-runtime-mblock-graph-stable-gemm (shape-freedom via device-side M; this is exec reuse, not shape freedom), and from the Batch-100 rebind rule (name-checks cudaGraphExecUpdate as an ANALOGY; this is the gated-sharing mechanism itself). Source: satellitedown/cinference @ 37814b1e -- src/core/decode_graph.h:28-31 + decode_graph.cpp:62-81 (FNV-1a offset 1469598103934665603 / prime 1099511628211, kernel nodes folded by `params.func` identity) + src/models/qwen3_5/program/graphs.cpp:70-78,360-384. Batch 178 / Plan 171 / Research 209.".to_string(),
            ref_shape: "// naive: one executable per profile -- every batch-size/frontier switch\n// re-instantiates a graph, even when the captured topology is identical\n// and only node params differ.\nstruct Profile {\n    batch: u32,\n    frontier: (u32, u32),\n}\n\nfn exec_for_naive(profiles: &[Profile]) -> usize {\n    profiles.len() // N executables for N profiles; every switch re-instantiates\n}".to_string(),
            opt_pattern: "// optimized: hash the CAPTURED graph (order-sensitive: node types,\n// kernel nodes keyed by function identity). Equal signature == unchanged\n// topology == ONE shared executable, updated in place across its\n// profiles; a signature change is the ONLY re-capture trigger.\n#[derive(PartialEq, Eq, Clone, Copy)]\nenum NodeType {\n    Kernel(usize), // identity of the kernel FUNCTION (not its params)\n    Memcpy,\n    Memset,\n}\n\nfn topology_signature(nodes: &[NodeType]) -> (usize, u64) {\n    // FNV-1a over the captured sequence -- ORDER-SENSITIVE by construction\n    let mut hash: u64 = 1469598103934665603;\n    for node in nodes {\n        let payload = match node {\n            NodeType::Kernel(f) => (*f as u64 + 1).wrapping_mul(1000003),\n            NodeType::Memcpy => 2,\n            NodeType::Memset => 3,\n        };\n        hash = (hash ^ payload).wrapping_mul(1099511628211);\n    }\n    (nodes.len(), hash)\n}\n\nfn exec_classes(profiles: &[&[NodeType]]) -> usize {\n    let mut sigs: Vec<(usize, u64)> = Vec::new();\n    for nodes in profiles {\n        let sig = topology_signature(nodes);\n        if !sigs.contains(&sig) {\n            sigs.push(sig); // one executable PER TOPOLOGY CLASS\n        }\n    }\n    sigs.len() // class-internal switches take the cudaGraphExecUpdate path\n}".to_string(),
        },

        // ── N: the EXACT-widening decision -- when a packed dtype widens
        // losslessly, the cheap-precision MMA is legal ──────────────────
        // Source: small_t_k8v4.cuh:8-11 (verbatim) + the T1 reframe (the
        // verdict's generic-fp16-accumulation framing was WRONG).
        KernelRule {
            rule_id: "exact-widening-enables-fp16-pv-accumulation".to_string(),
            gpu_concept: "The dtype decision that licenses a cheap-precision MMA accumulator: a packed value format that widens EXACTLY (losslessly) to a wider compute dtype permits the narrow accumulator inside the product loop; a format whose widening is LOSSY forbids it -- the widening's exactness is the entire legality question, never a generic 'fp16 accumulation is fine' heuristic. Source, verbatim (small_t_k8v4.cuh:8-11): 'Rotated V uses group-16 packed NVFP4 and widens exactly to FP16 at half scale for the PV MMA, which accumulates each 32-key product in FP16 before adding it to the FP32 accumulator. Split numerators and inverse rotation remain FP32.' The regime split the sentence carries: the PV PRODUCT (32 keys) accumulates in FP16 -- legal BECAUSE the NVFP4-to-FP16 widening at half scale is exact, so each product's operands and every intermediate sit inside FP16's exact-product envelope -- while the SPLIT NUMERATORS and the inverse rotation stay FP32 (the parts whose arithmetic is not covered by the exactness argument). TOLERANCE STRATEGY (the lossy-surface promotion law): the greedy-oracle -- the source's own 'greedy speculative output still matches plain target decoding' -- plus the per-family retention walk (the Issue-750-T3 precedent: aggregate perplexity flat is NOT evidence; per-family conditional behavior is). Measured (source-reported): passes 2-4 bit-exact with per-pass deltas quoted; pass 1 changed attention numerics and carries the acceptance-conflation caveat ('Tokens per round differ between the builds ... round time and time to first token are the engine comparison'). ANTI-REGIME (the kinship contrast that IS the rule): per-block-int32-chunk-rescale-fp32-accum (entries_gpu_33) refuses the fp16 accumulator -- 'never an fp16 accumulator' -- because ITS widening is lossy; that refusal and this permission are the two halves of ONE decision, keyed on the widening's exactness. Kinship: fast-accumulate-periodic-promote-bounded-error (entries_gpu_40) is the bounded-ERROR family (fp16-within-chunk with an fp32 shadow + periodic promote -- error is bounded, not zero); exact widening needs no bound because the error is zero at the product level. THE FORMAT NOTE (license hygiene for our silicon): NVFP4 block-scaled FP4 is Blackwell tcgen05 -- the 4090 has no hardware for it; the RULE is the widening-decision class, which instantiates on any silicon wherever a packed dtype widens losslessly (int8->int32 pairs, fp16-pair->fp32, sign-magnitude ternary->integer). Source: satellitedown/cinference @ 37814b1e -- src/ops/softmax_attention/dense/causal_cache/small_t_k8v4.cuh:8-11. Batch 178 / Plan 171 / Research 209. RIDER (Batch 193, mlxfast-bonsai2 @ 0c61273, Hadamard.swift:1341-1360): the ROUTING instance — a BF16 activation reading a vocabulary head at verify width 'is widened to FP32, exactly, and served by the tensor route's int8 form', streaming the head rows 'at about 544 GB/s on M5 Max, against about 305 for the FP16-read head kernel' (source-reported); exact widening licenses the PATH choice, not just the accumulator, and the verify-bounded-consumer clause ('never an emitted token' — the products feed the drafter's own top-k only; the target verifies every draft) carries the lossy-surface guard. Batch 193 / Plan 190 / Research 225.".to_string(),
            ref_shape: "// naive: the dtype is chosen by a generic heuristic -- 'fp16 MMA is\n// faster, accumulate narrow' -- applied whether or not the packed\n// format's widening into that accumulator is exact.\nfn pv_accumulate_by_heuristic(packed_v: &[u8], p: &[f32], out: &mut [f32]) {\n    let mut acc16 = half::ZERO; // fp16 accumulator, chosen for MMA throughput\n    for (k, pk) in p.iter().enumerate() {\n        let v = widen_lossy(packed_v[k]); // LOSSY widen: the product error is\n        // unbounded relative to the reference -- every product compounds it\n        acc16 = half::mul_add(half::from_f32(*pk), v, acc16);\n    }\n    out[0] = acc16.to_f32();\n}\n\nfn widen_lossy(_code: u8) -> half { half::ZERO } // placeholder: lossy decode".to_string(),
            opt_pattern: "// optimized: the accumulator precision is KEYED ON THE WIDENING'S\n// EXACTNESS. A format that widens losslessly (each element's decode is\n// exact at the target precision) licenses the narrow product accumulator;\n// a lossy widening refuses it -- the split numerators stay wide either way.\ntrait Widen {\n    const EXACT: bool; // the entire legality question\n    fn widen(code: u8) -> Self;\n}\n\nfn pv_accumulate_by_exactness<T: Widen + Copy>(packed_v: &[u8], p: &[f32], out: &mut [f32]) {\n    if T::EXACT {\n        // exact widening: each 32-key product sits inside the narrow\n        // envelope -- the narrow accumulator is LEGAL\n        let mut acc16 = half::ZERO;\n        for (k, pk) in p.iter().enumerate() {\n            let v: T = T::widen(packed_v[k]);\n            acc16 = half::mul_add(half::from_f32(*pk), v_as_half(v), acc16);\n        }\n        out[0] = acc16.to_f32(); // added to the FP32 split numerator outside\n    } else {\n        // lossy widening: REFUSE -- accumulate at the wide precision\n        // (the per-block-int32-chunk-rescale-fp32-accum posture)\n        let mut acc32 = 0.0f32;\n        for (k, pk) in p.iter().enumerate() {\n            acc32 = f32::mul_add(*pk, v_as_f32(T::widen(packed_v[k])), acc32);\n        }\n        out[0] = acc32;\n    }\n}\n\nfn v_as_half<T: Copy>(_v: T) -> half { half::ZERO }\nfn v_as_f32<T: Copy>(_v: T) -> f32 { 0.0 }".to_string(),
        },

        // ── E: warp-role specialization by query width -- scores in
        // registers as the PV operand; loader/compute split ─────────────
        // Source: small_t_k8v4.cuh:13-17 (the two-regime contract) + the
        // post-pin K8V4 warp trio (e165ffb/42e4b36/2d77e27) as the
        // regime-clause evidence.
        KernelRule {
            rule_id: "wide-verify-warp-specialized-scores-in-registers-pv".to_string(),
            gpu_concept: "Two-regime kernel selection by QUERY WIDTH for split-KV attention: NARROW query blocks keep the tiled kernel where producer warps score a key tile and publish P through SHARED memory to all warps; WIDE blocks (a complete verify width) go warp-specialized where each compute warp OWNS one row tile for the whole split and KEEPS ITS SCORES IN REGISTERS AS THE PV OPERAND while dedicated loader warps stream and widen the K/V tiles -- P never touches shared memory in the wide arm. Source, verbatim (small_t_k8v4.cuh:13-17): 'Narrow query blocks (up to three 16-row tiles) use the tiled kernel: producer warps score a key tile and publish P through shared memory to all warps for PV. Wide blocks (a complete 27B verify width) use the warp-specialized kernel: each compute warp owns one 16-row tile for the whole split and keeps its scores in registers as the PV operand, while two loader warps stream and widen the K/V tiles, so the Tensor Core work of one warp overlaps the softmax of another.' The MECHANISM is the warp-ROLE split (score/compute/loader) bought by the width: at narrow width there is too little per-warp work to amortize the specialization (the smem publish is fine); at wide width the register-resident P removes the smem round-trip AND the role split lets tensor-core work of one warp overlap the softmax of another. sm_89 REGIME CLAUSE (the Ada consumer constraint): consumer Ada has NO setmaxnreg -- warp-specialized splits SHARE ONE register allocation (the setmaxnreg-fit-gate-elected-arrive kinship, entries_gpu_37), so the split's register budget is bounded by the whole block, not per-role -- budget the roles together on Ada-class parts. POST-PIN EVIDENCE (the trio this batch read at master +9, all bit-identical by their own clauses): (a) e165ffb -- the role split ALONE left compute warps 4-5 half-idle; the fix hands each row tile's P fragments to warp 4+(r&1) which accumulates the TAIL column tiles, staged in the packed-V region's DEAD bytes after widening ('Every ... same operations in the same tile order, so outputs are bit-identical' at 42e4b36's tile order); (b) 42e4b36 -- the SAME role-split at PROMPT width: score warps run QK+online-softmax of tile j into double-buffered P tiles while PV warps accumulate tile j-1 (tensor pipes were idle ~40% of each key tile; attention 1313->1029us @8K, 4885->3776us @32K; product prefill +6% @32K, +16% @131K); (c) 2d77e27 -- the alternation variant: two 4-warp score groups ALTERNATE key tiles so one group's QK overlaps the other's softmax, with only the running row max/sum crossing groups via per-row-tile mbarriers ('Row sums keep the two 32-key halves and their order, so outputs are bit-identical'; 1177->1124us @8K, +2.9% @131K). All three numbers source-reported (RTX 5090). REGIME: wide query blocks where per-warp work amortizes the role split; ANTI-REGIME: narrow blocks (the tiled/smem form is the right one -- the source's own narrow arm), or a register budget that cannot hold the P fragments (the Ada shared-allocation clause). Kinship: compute-role-split-by-accumulator-pressure (entries_gpu_29 -- roles split BY PRESSURE; here by STAGE and width) + the cpasync-multistage rider (same batch: the loader staging pipeline this split consumes). Distinct from every smem-publish attention rule (those optimize the publish; this REMOVES it at width). Source: satellitedown/cinference @ 37814b1e (+ e165ffb/42e4b36/2d77e27 read post-pin) -- src/ops/softmax_attention/dense/causal_cache/small_t_k8v4.cuh:13-17 + prompt_k8v4.cuh. Batch 178 / Plan 171 / Research 209.".to_string(),
            ref_shape: "// naive: one kernel shape for every width -- every warp scores a tile,\n// publishes P through shared memory, barriers, then every warp runs PV on\n// the published fragments (the smem round-trip at EVERY width).\nfn attention_one_shape(q_rows: usize, p_scratch: &mut [f32], scores: &[f32]) -> f32 {\n    let mut acc = 0.0f32;\n    for r in 0..q_rows {\n        p_scratch[r] = scores[r]; // publish P via smem\n        // ... barrier: all warps wait for the publish ...\n        acc += p_scratch[r] * 1.0; // PV reads P back from smem\n    }\n    acc\n}".to_string(),
            opt_pattern: "// optimized: kernel SHAPE keyed on query width. Narrow: the tiled/smem\n// publish (left as-is -- the right shape there). Wide: warp SPECIALIZATION\n// -- compute warps own row tiles and keep scores IN REGISTERS as the PV\n// operand; loader warps stream the K/V tiles; tensor-core work overlaps\n// softmax across warps.\nenum QueryWidth {\n    Narrow, // <= three 16-row tiles: the tiled kernel, smem publish\n    Wide,   // full verify width: warp-specialized, registers-P\n}\n\nfn attention_two_regime(width: QueryWidth, q_rows: usize, scores: &mut [f32]) -> f32 {\n    match width {\n        QueryWidth::Narrow => {\n            let mut acc = 0.0;\n            for r in 0..q_rows {\n                acc += scores[r]; // smem publish is fine at narrow width\n            }\n            acc\n        }\n        QueryWidth::Wide => {\n            // PER-WARP OWNED REGISTERS: scores[r] stays in the compute warp's\n            // registers AS the MMA operand -- no smem round-trip, no publish\n            // barrier; loader warps fill the K/V staging in parallel\n            let mut warp_acc = 0.0f32;\n            let row_tile = 0; // this warp OWNS tile 0 for the whole split\n            for r in row_tile * 16..(row_tile + 1) * 16.min(q_rows) {\n                scores[r] = normalize_in_reg(scores[r]);\n                warp_acc += scores[r]; // P is the register operand directly\n            }\n            warp_acc\n        }\n    }\n}\n\nfn normalize_in_reg(s: f32) -> f32 { s }".to_string(),
        },

        // ── E: an expensive per-lane epilogue justifies REDUNDANT row
        // recompute across CTAs -- with a measured slice sweep ──────────
        // Source: nvfp4_rmsnorm_quantize.cu:17-20 (the sweep, verbatim).
        KernelRule {
            rule_id: "row-slice-expensive-epilogue-across-ctas".to_string(),
            gpu_concept: "When a row-parallel kernel's per-lane epilogue is EXPENSIVE relative to its row-statistics pass, split each row ACROSS CTAs -- each slice redundantly recomputing the row statistics it needs -- to buy epilogue parallelism; the slice count is a MEASURED dial with a non-monotone optimum, never 'more slices is better'. Source, verbatim (nvfp4_rmsnorm_quantize.cu:17-20): 'Quantizing costs three IEEE divisions per lane and step, so five CTAs share each row, two of the ten steps apiece (T=16: 1, 2, 5 and 10 slices measured 2.94, 2.24, 1.82 and 2.14 us).' The sweep IS the decision content: 1->2->5 slices improves (2.94 -> 2.24 -> 1.82 us -- the epilogue parallelism wins), and 10 slices REGRESSES (2.14 us -- the redundant row-statistics recompute and the per-slice fixed cost overtake the parallelism gain); the optimum sits at 5 for THIS kernel, and the dial must be swept per kernel, not inherited. The cost asymmetry that licenses the trade: the row statistics (max/sum over the row) are CHEAP to recompute per slice, while the epilogue (three IEEE divisions per lane per step) dominates -- inverting that ratio inverts the rule. REGIME: row-statistics cheap + epilogue expensive + rows too few to fill the device alone. ANTI-REGIME: rows already saturate the grid (slicing adds recompute for no occupancy gain); statistics expensive relative to the epilogue (recompute dominates -- keep one CTA per row); epilogue trivial (the split is pure overhead). Kinship: epilogue-must-be-workgroup-local (same-batch adjudication input -- WHERE the epilogue runs; this is the SEPARATE question of trading redundant recompute for its PARALLELISM across CTAs), and the 7-rule epilogue family it sits beside. Distinct from splitk-atomic-free-contention-threshold / split-k rules (those split the REDUCTION for occupancy; this splits a ROW for epilogue parallelism -- the recompute is redundant by design, not a partial-sum tree). Source: satellitedown/cinference @ 37814b1e -- src/ops/kernels/nvfp4_rmsnorm_quantize.cu:17-20 (measured on RTX 5090, T=16). Batch 178 / Plan 171 / Research 209.".to_string(),
            ref_shape: "// naive: one CTA per row -- the row's expensive epilogue (3 IEEE\n// divisions per lane per step) serializes inside the row's CTA while the\n// device idles beyond the row count.\nfn quantize_rows_one_cta(rows: &[f32], width: usize) -> Vec<u8> {\n    let mut codes = vec![0u8; rows.len()];\n    for (r, row) in rows.chunks(width).enumerate() {\n        let stats = row_stats(row); // max/sum -- cheap\n        for (i, v) in row.iter().enumerate() {\n            codes[r * width + i] = quantize_expensive(*v, &stats); // 3 divisions/lane\n        }\n    }\n    codes\n}\n\nfn row_stats(row: &[f32]) -> (f32, f32) { (row.iter().cloned().fold(0.0, f32::max), row.len() as f32) }\nfn quantize_expensive(_v: f32, _s: &(f32, f32)) -> u8 { 0 }".to_string(),
            opt_pattern: "// optimized: 5 CTAs share each row (2 steps apiece); each slice\n// REDUNDANTLY recomputes the cheap row stats, buying epilogue\n// parallelism. The slice count is a measured dial with a non-monotone\n// optimum: 1/2/5/10 slices measured 2.94/2.24/1.82/2.14 us -- 10\n// REGRESSES (recompute + fixed cost overtake the parallelism).\nconst ROW_SLICES: usize = 5; // the measured optimum for THIS kernel, T=16\n\nfn quantize_rows_sliced(rows: &[f32], width: usize, steps: usize) -> Vec<u8> {\n    let mut codes = vec![0u8; rows.len()];\n    for (r, row) in rows.chunks(width).enumerate() {\n        let per_slice = steps.div_ceil(ROW_SLICES);\n        for s in 0..ROW_SLICES {\n            // each CTA-slice recomputes the CHEAP stats itself -- redundant\n            // by design, the price of epilogue parallelism\n            let stats = row_stats(row);\n            for step in s * per_slice..((s + 1) * per_slice).min(steps) {\n                for (i, v) in row.iter().enumerate() {\n                    codes[r * width + i] = quantize_step(*v, &stats, step);\n                }\n            }\n        }\n    }\n    codes\n}\n\nfn quantize_step(_v: f32, _s: &(f32, f32), _step: usize) -> u8 { 0 }".to_string(),
        },

        // ── B: merging 32 per-lane sorted top-k lists across a warp -- 5
        // shuffle-butterfly rounds, no smem, no barriers ────────────────
        // Source: linear_topk/merge.cu:14-60 (the bitonic network + the
        // butterfly merge, verbatim at :49-52).
        KernelRule {
            rule_id: "warp-bitonic-topk-merge-shuffle".to_string(),
            gpu_concept: "Merging N=32 per-lane sorted top-k lists into one warp-wide top-k without shared memory or barriers: pack (score, id) into one u64 key (the score in the high bits so the integer compare IS the float compare -- the packed-key law), sort each lane's k keys with a bitonic network, then run log2(32)=5 __shfl_xor butterfly rounds where partner lists exchange and keep the combined top-k -- the merge invariant, verbatim (merge.cu:49-52): 'Five butterfly rounds merge partner lists: max(A[i], B[15 - i]) is a bitonic sequence holding the top kLinearTopK of both lists, which four compare-exchange layers sort descending. Afterwards every lane holds the same merged list.' The mechanism is the SHUFFLE-ButTERFLY MERGE itself: each round partners at distance 1,2,4,8,16; each lane shuffles its k keys to the partner and both sides select the combined top-k from the two sorted lists (the max-of-mirrored-indices trick: the top-k of A+B is the max over A[i] vs B[k-1-i] pairs, a bitonic sequence one local sort resolves); after 5 rounds every lane independently holds the warp's merged answer -- no smem round-trip, no __syncthreads, no cross-warp reduction tree. REGIME: one warp's worth of partitions (32 lists), k small (the k-element register array per lane), the result needed warp-uniform or per-lane-equal. ANTI-REGIME: more than 32 input lists (needs the smem path or a second level), k large (register pressure beats the shuffle savings), or the lists unsorted (sort first -- the per-lane bitonic is the entry fee). Kinship (family-adjacent, mechanism-novel): the topk/select family -- topk-select-nth-over-full-vocab-sort, order-stable-topk-via-index-sort, device-side-argmax-minimal-download (the ds4 MTP-select rider) -- all smem/sort-shaped; cross-simd-bitonic-alternating-bank-exchange (entries_gpu_13) is the SIMD-lane bitonic EXCHANGE pattern (this is the MERGE-of-sorted-lists shape riding __shfl_xor); ballot-matrix-tie-rank handles the tie discipline. Distinct from warp-shuffle-intrinsics-for-sub-warp-reduction (reduces VALUES; this merges SORTED LISTS preserving k elements each). Source: satellitedown/cinference @ 37814b1e -- src/ops/linear_topk/merge.cu:14-60. Batch 178 / Plan 171 / Research 209.".to_string(),
            ref_shape: "// naive: the 32 per-lane top-k lists round-trip through shared memory\n// (or global) for a block-wide sort -- two barriers plus a full re-sort of\n// 32*k elements to find the top k.\nfn merge_lists_via_scratch(lane_lists: &[[u64; 16]; 32], smem: &mut Vec<u64>) -> [u64; 16] {\n    smem.clear();\n    for list in lane_lists {\n        smem.extend_from_slice(list); // 32*16 keys through smem\n    }\n    smem.sort_unstable_by(|a, b| b.cmp(a)); // full re-sort (barriers elided)\n    let mut out = [0u64; 16];\n    out.copy_from_slice(&smem[..16]);\n    out\n}".to_string(),
            opt_pattern: "// optimized: 5 __shfl_xor butterfly rounds. Each lane's k=16 keys are\n// sorted (bitonic); partners at distance d exchange lists; the combined\n// top-k of two sorted lists is max(A[i], B[15-i]) -- a bitonic sequence\n// four compare-exchange layers re-sort. After round 5 every lane holds\n// the same merged top-k. No smem, no barriers.\nfn merge_lists_butterfly(lane: usize, lane_lists: &[[u64; 16]; 32]) -> [u64; 16] {\n    let mut keys = lane_lists[lane]; // registers only\n    keys.sort_unstable_by(|a, b| b.cmp(a)); // the per-lane bitonic entry fee\n    let mut offset = 1usize;\n    while offset < 32 {\n        let partner = lane ^ offset; // __shfl_xor partner at distance d\n        let other = lane_lists[partner]; // the shuffled-in partner list\n        // top-16 of the two sorted 16-lists: max(A[i], B[15-i]) pairwise --\n        // a bitonic sequence holding exactly the combined top-k\n        let mut merged = [0u64; 16];\n        for i in 0..16 {\n            merged[i] = keys[i].max(other[15 - i]);\n        }\n        // four compare-exchange layers sort the bitonic sequence descending\n        let mut size = 2usize;\n        while size <= 16 {\n            for i in 0..16 {\n                let j = i | (size - 1);\n                if j > i && i & (size << 1).saturating_sub(1) < size {\n                    // descending exchange within the block\n                    if merged[i] < merged[j] {\n                        merged.swap(i, j);\n                    }\n                }\n            }\n            size <<= 1;\n        }\n        keys = merged;\n        offset <<= 1;\n    }\n    keys // every lane independently holds the warp's answer\n}".to_string(),
        },
    ]
}
